questions.solution:
-- Add column
ALTER TABLE Students ADD COLUMN phone_number VARCHAR(15);

-- Rename column (MySQL 8+)
ALTER TABLE Students RENAME COLUMN gpa TO cgpa;

-- Drop column
ALTER TABLE Students DROP COLUMN age;

-- Add index
CREATE INDEX idx_department ON Students(department);

-- Or using ALTER TABLE
ALTER TABLE Students ADD INDEX idx_department (department);

-- Add status column
ALTER TABLE Students ADD COLUMN status VARCHAR(20) DEFAULT 'active';

-- Update CS students GPA (cap at 10.0)
UPDATE Students
SET gpa = LEAST(gpa + 0.2, 10.0)
WHERE department = 'CS';

-- Set probation for low GPA
UPDATE Students
SET status = 'probation'
WHERE gpa < 5.0;

-- Using NOT IN
DELETE FROM Students
WHERE student_id NOT IN (
    SELECT DISTINCT student_id FROM Enrollments
);

-- Using NOT EXISTS (more efficient for large datasets)
DELETE FROM Students s
WHERE NOT EXISTS (
    SELECT 1 FROM Enrollments e
    WHERE e.student_id = s.student_id
);

