-- Wrong:
SELECT dept, AVG(gpa) FROM Students WHERE AVG(gpa) > 8 GROUP BY dept;

-- Correct:
SELECT dept, AVG(gpa) FROM Students GROUP BY dept HAVING AVG(gpa) > 8;
